import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import Database from 'better-sqlite3';
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { runProductionReconcileTick } from '../../core/incremental-indexing/application/production-reconciler.mjs';
import { LateInteractionIndex } from '../../core/ranking/late-interaction-index.js';

// LI skips @generated files. When a file flipped between generated and hand-written, only
// the chunks that changed got LI ops: the unchanged ones kept (or never got) LI docs, unlike a
// full build of the same file.
const MODEL_INFO = Object.freeze({ provider: 'test', model: 'fake', dimension: 8, hnswDimension: 8 });
const vectorEncoder = async (texts) => texts.map((t, i) => Float32Array.from({ length: 8 }, (_, k) => ((t.length + i + k * 13) % 97) / 97));
const liEncoder = async (texts) => texts.map((t) => [Float32Array.from({ length: 8 }, (_, k) => Math.sin(t.length + k))]);

function body(header) {
  const fn = (name) => [`export function ${name}(input) {`, ...Array.from({ length: 40 }, (_, i) => `  const v${i} = input.${name}${i} ?? ${i};`), '  return input;', '}'].join('\n');
  return `${header}\n${fn('alpha')}\n\n${fn('beta')}\n`;
}

describe('LI when a file flips between generated and hand-written', () => {
  let projectRoot;
  let stateDir;
  const rel = 'src/gen.js';
  beforeEach(() => {
    projectRoot = mkdtempSync(join(tmpdir(), 'ss-genflip-'));
    stateDir = join(projectRoot, '.sweet-search');
    mkdirSync(join(projectRoot, 'src'), { recursive: true });
    mkdirSync(stateDir, { recursive: true });
  });
  afterEach(() => { rmSync(projectRoot, { recursive: true, force: true }); });

  async function tick(content) {
    writeFileSync(join(projectRoot, rel), content);
    writeFileSync(join(stateDir, 'index-maintainer-queue.jsonl'), `${JSON.stringify({ file_path: rel })}\n`);
    await runProductionReconcileTick({
      projectRoot, stateDir, vectorEncoder, liEncoder, modelInfo: MODEL_INFO,
      logger: { info() {}, warn() {}, error() {} }, config: { filesPerTick: 10, cpuBudgetMs: 10_000 },
    });
  }
  const liveIds = () => {
    const db = new Database(join(stateDir, 'codebase.db'), { readonly: true });
    try { return new Set(db.prepare('SELECT id FROM vectors WHERE epoch_retired IS NULL').all().map((r) => r.id)); } finally { db.close(); }
  };
  const liIds = async () => {
    const idx = new LateInteractionIndex({ indexPath: join(stateDir, 'codebase-late-interaction.db'), loadExisting: true });
    await idx.init();
    return new Set(idx.documents.keys());
  };

  it('adds LI docs for every chunk when the header goes, and retires them all when it comes back', async () => {
    await tick(body('// hand-written module'));
    expect(liveIds().size).toBeGreaterThan(1);
    expect(await liIds()).toEqual(liveIds());

    await tick(body('// @generated by a tool'));
    expect(await liIds()).toEqual(new Set());

    await tick(body('// hand-written module'));
    expect(await liIds()).toEqual(liveIds());
  });
});
